{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const fail = (m) => { throw new ParseError(m, 0) }

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.c; return c === undefined || c === '#' || c === ';' }
}

function parseString(L) {
  const q = L.c
  L.i++
  let out = ''
  if (q === "'") {
    const j = L.s.indexOf("'", L.i)
    if (j < 0) fail('unterminated string')
    out = L.s.slice(L.i, j)
    L.i = j + 1
    return out
  }
  for (;;) {
    const c = L.c
    if (c === undefined) fail('unterminated string')
    L.i++
    if (c === '"') return out
    if (c !== '\\') { out += c; continue }
    const e = L.c
    if (e === undefined) fail('unterminated string')
    const ch = String.fromCodePoint(L.s.codePointAt(L.i))
    L.i += ch.length
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.slice(L.i, L.i + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else fail(`invalid escape \\${ch}`)
  }
}

function parseName(L) {
  const c = L.c
  if (c === '"' || c === "'") return parseString(L)
  if (!isNameChar(c)) fail('expected a name')
  const st = L.i
  while (isNameChar(L.c)) L.i++
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const parts = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c === '.') {
      L.i++
      L.ws()
      parts.push(parseName(L))
    } else {
      L.i = save
      return parts
    }
  }
}

// Walk through `parts` from `table`, creating tables; returns the final table.
function walk(table, parts, base) {
  let cur = table
  const path = [...base]
  for (const p of parts) {
    path.push(p)
    let n = cur.map.get(p)
    if (n === undefined) {
      n = newTable()
      cur.map.set(p, n)
    }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') fail(`${path.join('.')} is not a table`)
    cur = n
  }
  return cur
}

function assign(table, parts, value, base) {
  const t = walk(table, parts.slice(0, -1), base)
  const last = parts[parts.length - 1]
  if (t.map.has(last)) fail(`key ${[...base, ...parts].join('.')} is defined twice`)
  t.map.set(last, value)
}

function parseValue(L, path) {
  L.ws()
  const c = L.c
  if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return { t: 'string', v: parseString(L) }
  if (c === '[') {
    L.i++
    const items = []
    for (;;) {
      L.ws()
      if (L.c === ']') { L.i++; break }
      if (L.atEnd()) fail('unterminated array')
      items.push(parseValue(L, path))
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === ']') { L.i++; break }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  if (c === '{') {
    L.i++
    const tbl = newTable()
    L.ws()
    if (L.c === '}') { L.i++; return tbl }
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated inline table')
      const parts = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected = in an inline table')
      L.i++
      const v = parseValue(L, [...path, ...parts])
      assign(tbl, parts, v, path)
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === '}') { L.i++; break }
      fail('unterminated inline table')
    }
    return tbl
  }
  const st = L.i
  while (L.c !== undefined && !isWs(L.c) && L.c !== ',' && L.c !== ']' && L.c !== '}') L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  fail(`invalid value ${w}`)
}

function parseHeader(L, root, line) {
  const aot = L.s[L.i + 1] === '['
  L.i += aot ? 2 : 1
  L.ws()
  const parts = parseDotted(L)
  L.ws()
  const closeFail = () => fail('unterminated table header')
  if (L.c !== ']') closeFail()
  L.i++
  if (aot) {
    if (L.c !== ']') closeFail()
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const parent = walk(root, parts.slice(0, -1), [])
  const last = parts[parts.length - 1]
  const n = parent.map.get(last)
  if (aot) {
    if (n === undefined) {
      const t = newTable()
      parent.map.set(last, { t: 'array', items: [t], aot: true })
      return t
    }
    if (n.t !== 'array' || !n.aot) fail(`${parts.join('.')} is not an array of tables`)
    const t = newTable()
    n.items.push(t)
    return t
  }
  if (n === undefined) {
    const t = newTable()
    t.header = true
    parent.map.set(last, t)
    return t
  }
  if (n.t !== 'table') fail(`${parts.join('.')} is not a table`)
  if (n.header) fail(`table ${parts.join('.')} is defined twice`)
  n.header = true
  return n
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  lines.forEach((s, idx) => {
    try {
      const L = new Line(s)
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') return
      if (L.c === '[') {
        cur = parseHeader(L, root, idx + 1)
        return
      }
      const parts = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = parseValue(L, [])
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, parts, v, [])
    } catch (e) {
      if (e instanceof ParseError) e.line = idx + 1
      throw e
    }
  })
  return root
}
"}

